const std = @import("std");

pub fn main() !void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const api_key = std.process.getEnvVarOwned(allocator, "GEMINI_API_KEY") catch |err| {
        if (err == error.EnvironmentVariableNotFound) {
            std.debug.print("Error: The environment variable GEMINI_API_KEY is not set.\n", .{});
            return;
        }
        return err;
    };
    defer allocator.free(api_key);

    const uri_str = try std.fmt.allocPrint(
        allocator,
        "",
        .{api_key},
    );
    defer allocator.free(uri_str);

    const uri = try std.Uri.parse(uri_str);

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const payload =
        \\{
        \\  "model": "models/gemini-3.1-flash-image",
        \\  "input": "",
        \\  "tools": [
        \\    {
        \\      "type": "google_search"
        \\    }
        \\  ],
        \\  "generation_config": {
        \\    "temperature": 0.15,
        \\    "max_output_tokens": 65536,
        \\    "top_p": 0.95,
        \\    "thinking_level": "high",
        \\    "image_config": {
        \\      "image_size": "4K"
        \\    }
        \\  },
        \\  "response_modalities": [
        \\    "image"
        \\  ]
        \\}
    ;

    var response_body: std.Io.Writer.Allocating = .init(allocator);
    defer response_body.deinit();

    const res = try client.fetch(.{
        .location = .{ .uri = uri },
        .method = .POST,
        .payload = payload,
        .extra_headers = &.{
            .{ .name = "Content-Type", .value = "application/json" },
        },
        .response_writer = &response_body.writer,
    });

    if (res.status != .ok) {
        std.debug.print("HTTP Error {d}: {s}\n", .{ @intFromEnum(res.status), response_body.written() });
        return;
    }

    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, response_body.written(), .{});
    defer parsed.deinit();

    if (parsed.value == .object) {
        if (parsed.value.object.get("steps")) |steps_val| {
            if (steps_val == .array and steps_val.array.items.len > 0) {
                const last_step = steps_val.array.items[steps_val.array.items.len - 1];
                var out: std.Io.Writer.Allocating = .init(allocator);
                defer out.deinit();
                var write_stream: std.json.Stringify = .{
                    .writer = &out.writer,
                    .options = .{ .whitespace = .indent_2 },
                };
                try write_stream.write(last_step);
                try std.fs.File.stdout().writeAll(out.written());
                try std.fs.File.stdout().writeAll("\n");
                return;
            }
        }
    }

    try std.fs.File.stdout().writeAll(response_body.written());
    try std.fs.File.stdout().writeAll("\n");
}

